-- ************************************** OPERATIONS.WORK_ORDER
CREATE TABLE OPERATIONS.WORK_ORDER
(
 WORK_ORDER_ID          varchar(30) NOT NULL COMMENT 'Primary key for maintenance work order.',
 ADDRESS                string NOT NULL,
 SERVICE_LOCATION_ID    varchar(20) NOT NULL COMMENT 'Foreign key to Service Location.',
 SERVICE_REQUEST_ID     varchar(30) COMMENT 'Foreign key to Service Request (if work order created from request).',
 WORK_ORDER_DATE        date NOT NULL COMMENT 'Date when work order was created.',
 SCHEDULED_START_DATE   date NOT NULL COMMENT 'Scheduled start date for maintenance work.',
 ACTUAL_START_DATE      date COMMENT 'Actual start date of work.',
 ACTUAL_COMPLETION_DATE date COMMENT 'Actual completion date of work.',
 WORK_ORDER_STATUS      varchar(20) NOT NULL COMMENT 'Current status of work order (Scheduled, In Progress, Completed, Cancelled).',
 WORK_DESCRIPTION       varchar(500) COMMENT 'Description of maintenance work to be performed.',
 ASSIGNED_EMPLOYEE_ID   varchar(20) COMMENT 'ID of employee assigned to perform work.',
 LABOR_HOURS            decimal(8,2) COMMENT 'Hours spent on this work order.',
 MATERIALS_COST         decimal(12,2) COMMENT 'Cost of materials used.',

 CONSTRAINT PK_1 PRIMARY KEY ( WORK_ORDER_ID ),
 CONSTRAINT FK_1 FOREIGN KEY ( SERVICE_LOCATION_ID ) REFERENCES CUSTOMER.SERVICE_LOCATION ( SERVICE_LOCATION_ID )
)
COMMENT = 'Transaction table tracking maintenance and repair work orders.';
